  Definition Rbc (bc : Z) : Z := if (8 <=? bc) && (bc <=? 16) then (if bc =? 16 then 3 else 2) else 1.
  Definition mu (s : rstate) : Z :=
    if r_ip s <=? h - 7 then h - 7 - r_ip s + 5 else if r_ip s <? h - 4 then 4 else Rbc (r_bitCount s).

