  Lemma rbody_total s :
    CTL s -> POS s -> r_bitCount s < 32 ->
    exists fl, rbody buf maxSV1 s = Ok fl /\
      match fl with
      | Cont s' => CTL s' /\ POS s' /\ r_bitCount s' < 32 /\ r_charnum s < r_charnum s'
      | Brk s' => BRK s' /\ (r_remaining s' = 1 -> r_charnum s' <= maxSV1 /\ (tl <= 14 -> pws (r_nc s') (r_charnum s') = 2^tl))
