  Lemma rloop_total f : forall s,
    CTL s -> POS s -> r_bitCount s < 32 -> maxSV1 - r_charnum s < Z.of_nat f ->
    exists s', rloop buf maxSV1 f s = Ok s' /\ BRK s' /\
      (r_remaining s' = 1 -> r_charnum s' <= maxSV1 /\ (tl <= 14 -> pws (r_nc s') (r_charnum s') = 2^tl)).
