(* [comment removed for export] *)
Theorem read_ncount_total nc0 maxSVin buf :
  all_bytes buf -> 0 <= maxSVin -> maxSVin + 1 <= Zlength nc0 ->
  (exists nc maxSV tableLog n, read_ncount nc0 maxSVin buf = Ok (nc, maxSV, tableLog, n) /\
     length nc = length nc0 /\ 0 <= maxSV <= maxSVin /\ 5 <= tableLog <= 15 /\ 1 <= n <= Zlength buf /\
     (forall i, maxSV < i <= maxSVin -> Znth i nc = 0) /\ (forall i, maxSVin < i -> Znth i nc = Znth i nc0) /\
     (tableLog <= 14 -> (forall i, 0 <= i <= maxSV -> -1 <= Znth i nc) /\ wsum (firstn (Z.to_nat (maxSV + 1)) nc) = 2^tableLog))
